# Ensure the matrix matches the dimensions of the tokens
matrix = np.array(data['attention_matrix'])

def plot_attention(matrix, src_tokens, tgt_tokens):
    fig, ax = plt.subplots(figsize=(12, 8))
    
    # Create Heatmap
    sns.heatmap(matrix, annot=False, cmap='viridis', 
                xticklabels=src_tokens, yticklabels=tgt_tokens, ax=ax)

    # Set labels
    ax.set_xlabel('Source Tokens (Reactant)', fontsize=12, fontweight='bold')
    ax.set_ylabel('Target Tokens (Product)', fontsize=12, fontweight='bold')
    ax.set_title('Transformer Cross-Attention: Reactant to Product Mapping', fontsize=14)
    
    # Rotate labels for better readability
    plt.xticks(rotation=45, ha='right')
    plt.yticks(rotation=0)
    
    plt.tight_layout()
    plt.show()

# If using your full matrix from the previous message:
plot_attention(matrix, data['source_tokens'], data['target_tokens'])